INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 1, 'theory', 'Квиз: первая программа, типы и компиляция');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 1, 0, 'Что делает компоновщик при сборке программы на C?', '["Превращает C в ассемблер","Раскрывает #include и #define","Склеивает объектные файлы и библиотеки в исполняемый файл и расставляет адреса","Оптимизирует код"]', 2, 'Препроцессор раскрывает директивы, компилятор переводит в ассемблер, ассемблер даёт объектный файл, а компоновщик собирает всё в один ELF.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 1, 1, 'Чему равны -7 / 2 и -7 % 2 в C?', '["-3 и -1","-4 и 1","-3 и 1","-4 и -1"]', 0, 'Деление целых отбрасывает дробную часть (к нулю), остаток получает знак делимого — как в процессоре; питонское -4 и 1 — другое.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 1, 2, 'Что произойдёт при int x = INT_MAX; x = x + 1;?', '["x станет INT_MIN","Программа аварийно завершится","x останется равным INT_MAX","Неопределённое поведение: стандарт не определяет результат"]', 3, 'Переполнение знакового типа — UB: компилятор вправе считать, что его не бывает. Беззнаковые числа, напротив, заворачиваются по модулю.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 1, 3, 'Какое значение у неинициализированной локальной переменной int x;?', '["Всегда 0","Мусор: читать её нельзя","NULL","Минимальное значение int"]', 1, 'Локальные переменные не обнуляются; чтение даёт неопределённое поведение. Нули по умолчанию получают лишь глобальные и static-переменные (.bss).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 1, 4, 'Почему вызов printf("%d", 3.5) — ошибка?', '["Потому что 3.5 слишком длинное число","Потому что printf не печатает дробные","Метка %d не соответствует типу double: поведение не определено","Это нормально, число будет округлено"]', 2, 'Компилятор не обязан проверять соответствие метки и аргумента; несоответствие — UB. Включайте -Wall: он проверяет форматы.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 2, 'theory', 'Квиз: ветвления, циклы и функции');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 2, 0, 'Что произойдёт в switch, если в ветке case забыть break?', '["Выполнение «провалится» в следующую ветку","Компилятор откажется собирать","Выполнится только default","Программа завершится с ошибкой"]', 0, 'Проваливание (fall-through) — штатное поведение C: после тела ветки управление идёт дальше, пока не встретится break. Включайте -Wimplicit-fallthrough.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 2, 1, 'Как передаётся параметр int x в функцию?', '["По ссылке: изменения видны вызывающему","Через глобальную переменную","По значению: функция получает копию","Через стек всегда, регистры не используются"]', 2, 'В C все параметры передаются по значению; чтобы изменить чужую переменную, передают её адрес. Первые аргументы лежат в регистрах a0–a7.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 2, 2, 'Почему цикл for (size_t i = n - 1; i >= 0; i--) не заканчивается?', '["size_t знаковый","Потому что n мало","Компилятор убирает i--","i >= 0 для беззнакового всегда истинно, а 0 - 1 даёт максимум"]', 3, 'Беззнаковое число не бывает меньше нуля; при i == 0 декремент заворачивается в SIZE_MAX. Пишите for (size_t i = n; i-- > 0; ) или используйте знаковый тип.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 2, 3, 'Что хранится в регистре ra при вызове функции командой jal?', '["Результат функции","Адрес команды, на которую надо вернуться после ret","Указатель стека","Первый аргумент"]', 1, 'jal сохраняет адрес следующей команды в ra; вызванная функция при необходимости кладёт его в кадр, а ret выполняет переход по ra.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 2, 4, 'Что не так с выражением int x = i++ + ++i;?', '["Оно слишком длинное","++i нельзя писать справа","i меняется дважды между точками следования — неопределённое поведение","Результат всегда 0"]', 2, 'Порядок вычисления операндов + не определён, а двойное изменение одной переменной без точки следования — UB. Меняйте переменную не больше одного раза.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 3, 'theory', 'Квиз: указатели и массивы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 3, 0, 'Чему эквивалентно выражение a[i] для массива a?', '["&a + i","a + *i","(*a) + i","*(a + i)"]', 3, 'Индексация — запись для сдвига и разыменования: a + i сдвигает указатель на i элементов (i * sizeof(*a) байт), а звёздочка читает объект.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 3, 1, 'Чему равен sizeof(a) внутри функции void f(int a[])?', '["Размеру указателя (8 на 64-битной машине)","Размеру массива в байтах","Числу элементов","Нулю"]', 0, 'Массив-параметр «распадается» в указатель на первый элемент, и информация о длине теряется — её передают отдельным параметром.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 3, 2, 'Что значит const int *p?', '["Сам указатель нельзя менять, данные можно","Данные нельзя менять через p, сам указатель можно двигать","Нельзя менять ни то ни другое","p указывает на константу NULL"]', 1, 'Читают справа налево: p — указатель на int, который const. Для запрета перестановки указателя пишут int *const p.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 3, 3, 'Как правильно переинтерпретировать биты float как uint32_t?', '["*(uint32_t *)&f — приведением указателя","(uint32_t)f","Через memcpy в переменную uint32_t","Через void *"]', 2, 'Приведение указателя нарушает строгий алиасинг (UB). memcpy копирует байты, а компилятор превратит его в одну команду.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 3, 4, 'Что делает memmove(a + 1, a, 4 * sizeof a[0]) для int a[5]?', '["Копирует 4 байта","Сдвигает первые четыре элемента на одну позицию вправо, безопасно для пересечения областей","Копирует всё в начало","Ничего: области пересекаются"]', 1, 'memmove учитывает пересечение и копирует в нужном направлении; memcpy в такой ситуации — неопределённое поведение. Размер всегда в байтах.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 4, 'theory', 'Квиз: строки, структуры и union');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 4, 0, 'Сколько байт занимает строка "hello" в памяти?', '["5","6: пять символов и завершающий нуль","4","Зависит от платформы"]', 1, 'В конце каждого литерала добавляется байт 0. Поэтому sizeof "hello" равен 6, а strlen — 5; буфер под копию должен быть не короче 6 байт.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 4, 1, 'Что делает strncpy(dst, src, n), если src длиннее n?', '["Ставит нуль в конце dst","Возвращает ошибку","Обрезает src на месте","Копирует n байт и не ставит завершающий нуль"]', 3, 'strncpy — не «безопасный strcpy»: без места для нуля строка остаётся незавершённой. Надёжнее snprintf(dst, sizeof dst, "%s", src).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 4, 2, 'Почему sizeof(struct { char a; int b; char c; }) обычно равен 12, а не 6?', '["Поля выравниваются, и между ними и в конце вставляется заполнитель","Компилятор добавляет заголовок объекта","Строки всегда занимают по 4 байта","int занимает 8 байт"]', 0, 'int должен лежать по адресу, кратному 4; структура целиком выравнивается по самому строгому полю. Порядок int, char, char даёт 8.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 4, 3, 'Что произойдёт при записи в одно поле union и чтении другого?', '["Ошибка компиляции","Значение обнулится","Прочитаются те же байты, интерпретированные другим типом","Программа аварийно завершится"]', 2, 'Все поля union лежат по одному адресу. Чтобы знать, какое поле «активно», добавляют тег — получается помеченное объединение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 4, 4, 'Почему нельзя записывать struct в файл через fwrite(&s, sizeof s, 1, f) и читать на другой машине?', '["fwrite не умеет работать со структурами","Структуры слишком большие","Это работает всегда","В структуре есть заполнитель с мусором, а порядок байтов и выравнивание могут отличаться"]', 3, 'Раскладка зависит от платформы и компилятора. Для обмена сериализуйте поля по одному в договорённом порядке байтов.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 5, 'theory', 'Квиз: динамическая память и структуры данных');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 5, 0, 'Что неправильно в строке v->data = realloc(v->data, n);?', '["При неудаче realloc вернёт NULL, и старый блок будет потерян — утечка","Ничего: так и пишут","realloc нельзя вызывать на куче","Нужно сначала вызвать free"]', 0, 'Результат realloc сначала кладут во временную переменную, проверяют на NULL и только потом присваивают рабочему указателю — иначе при ошибке теряется единственный адрес старого блока.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 5, 1, 'Что произойдёт при двух вызовах free(p) подряд для одного и того же указателя?', '["Ничего: второй вызов игнорируется","Программа вернёт NULL","Блок освободится дважды корректно","Неопределённое поведение: повреждение кучи"]', 3, 'Double free — ошибка владения. Обнуляйте указатель после free (free(NULL) безопасен) и соблюдайте правило «один владелец».');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 5, 2, 'Почему добавление в конец динамического массива с удвоением ёмкости — амортизированно O(1)?', '["Потому что realloc мгновенный","Дорогие копирования случаются редко, и их суммарная стоимость растёт линейно с числом добавлений","Потому что ёмкость не растёт","Потому что массив хранится на стеке"]', 1, 'При ёмкости 1, 2, 4, 8, … все перекопирования суммарно дают порядка 2n операций на n добавлений — константа на добавление в среднем.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 5, 3, 'Какой in-order обход двоичного дерева поиска даёт ключи?', '["В порядке вставки","По убыванию","По возрастанию","В случайном порядке"]', 2, 'Обход «левое поддерево — узел — правое поддерево» в дереве поиска идёт по возрастанию ключей: все левые меньше узла, все правые больше.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 5, 4, 'Для чего нужен AddressSanitizer (-fsanitize=address)?', '["Ускоряет программу","Находит выход за границы буфера, use-after-free и утечки","Сжимает память","Проверяет стиль кода"]', 1, 'Он вставляет проверки вокруг обращений к памяти и сообщает строку ошибки и место выделения; с ним же работает детектор утечек.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 6, 'theory', 'Квиз: указатели на функции и обобщённый код');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 6, 0, 'Что объявляет запись int (*op)(int, int);?', '["Функцию, возвращающую указатель на int","Массив из двух указателей","Указатель на функцию с двумя int, возвращающую int","Указатель на два int"]', 2, 'Читаем изнутри: op — указатель (*op), на функцию с параметрами (int, int), возвращающую int. Скобки вокруг звёздочки обязательны: без них получилась бы функция, возвращающая int *.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 6, 1, 'Почему return x - y; в функции сравнения для qsort — плохая идея?', '["Разность может переполниться и дать неверный знак","qsort принимает только значения 0 и 1","Вычитание медленнее сравнения","Нельзя вычитать int"]', 0, 'Для больших по модулю значений разность выходит за диапазон int: это неопределённое поведение или неверный знак. Безопасно: (x > y) - (x < y).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 6, 2, 'Что получает функция сравнения qsort, если сортируют массив char *?', '["Сами строки типа char","Длины строк","Индексы элементов","Указатели на ячейки массива, то есть указатели на char *"]', 3, 'qsort передаёт адреса элементов массива. Элемент — char *, значит, адрес элемента — char * const *: сначала приводим, затем разыменовываем и только после этого зовём strcmp.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 6, 3, 'Зачем рядом с указателем на колбэк передают void *ctx?', '["Чтобы колбэк мог вернуть значение","Чтобы передать колбэку данные: пара «функция + контекст» заменяет замыкание","Чтобы ускорить вызов","Чтобы компилятор проверил типы"]', 1, 'У функции в C нет захваченных переменных. Контекст — ручное замыкание: вызывающий отвечает, чтобы он прожил до последнего вызова колбэка.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 6, 4, 'Что даёт таблица указателей на функции вместо длинного switch?', '["Типобезопасность без приведений","Один косвенный переход вместо цепочки сравнений; новый вариант — строка в таблице","Возможность подставить тело функции в место вызова","Отсутствие косвенных переходов"]', 1, 'Индекс выбирает обработчик за константное время. Платой служит косвенный переход: компилятору труднее оптимизировать и подставить тело функции.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 7, 'theory', 'Квиз: препроцессор, макросы и заголовочные файлы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 7, 0, 'Для чего нужен сторож включения (#ifndef X_H / #define X_H / … / #endif) в заголовке?', '["Чтобы заголовок компилировался быстрее на любых платформах","Чтобы повторное подключение заголовка не определяло типы второй раз","Чтобы запретить подключать заголовок из других файлов","Чтобы шифровать содержимое заголовка"]', 1, 'Заголовок часто подключается несколько раз по цепочке include. Сторож пропускает текст при повторе, и структуры не определяются дважды.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 7, 1, 'Во что развернётся SQ(a + 1) при #define SQ(x) x * x?', '["(a + 1) * (a + 1)","a * a + 1","Ошибка: макросу нельзя передавать выражения","a + 1 * a + 1"]', 3, 'Препроцессор подставляет текст: получится a + 1 * a + 1, где умножение выполняется раньше сложения. Поэтому параметры в теле макроса берут в скобки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 7, 2, 'Зачем макрос из нескольких операторов оборачивают в do { … } while (0)?', '["Чтобы макрос вёл себя как один оператор — в том числе в if без фигурных скобок","Чтобы макрос выполнялся несколько раз","Чтобы он работал быстрее обычной функции","Чтобы компилятор не оптимизировал его"]', 0, 'Без обёртки в ветке if без скобок под условие попадёт лишь первый оператор. do-while(0) выполняется ровно раз, а точка с запятой после вызова превращает запись в обычный оператор.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 7, 3, 'Что даст S(N) при #define N 5, #define S1(x) #x и #define S(x) S1(x)?', '["Число 5","Строку \"N\" — как и S1(N)","Строку \"5\": аргумент раскрывается до передачи внутреннему макросу","Ошибку компиляции"]', 2, 'Оператор # применяется к аргументу без раскрытия: S1(N) даёт "N". Во внешнем макросе S аргумент сначала раскрывается в 5, и S1 получает уже 5 — выходит "5".');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 7, 4, 'Чем лучше всего заменить макрос MAX(a, b), где аргумент вычисляется дважды?', '["Ещё одной парой скобок вокруг параметров","Директивой #undef","Макросом с двойной решёткой","Статической встраиваемой функцией static inline — аргумент вычисляется один раз, есть типы"]', 3, 'У функции аргументы вычисляются единожды, есть проверка типов, а компилятор по-прежнему может подставить тело. Скобки двойное вычисление не устраняют.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 8, 'theory', 'Квиз: ввод и вывод, форматирование и буферизация');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 8, 0, 'Что возвращает sscanf?', '["Число прочитанных символов","Всегда 0 при успехе","Указатель на остаток строки","Число успешно разобранных и записанных полей (или EOF)"]', 3, 'Именно результат sscanf показывает, сколько полей реально разобрано: если вернулось меньше ожидаемого, часть значений остались неизменёнными, и ими пользоваться нельзя.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 8, 1, 'Что произойдёт при snprintf(buf, 8, "%d", 123456789)?', '["В buf окажутся 7 символов и ноль, а вернётся 9 — длина полного результата","Запишется 9 цифр и память за буфером будет испорчена","Вернётся −1 и buf не изменится","Программа завершится с ошибкой"]', 0, 'snprintf не пишет больше size − 1 символа и всегда ставит ноль. Возвращает длину, которая получилась бы без усечения (9), поэтому по возврату узнают, что текст усечён.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 8, 2, 'Почему цикл while (!feof(f)) { fgets(…); обработать(…); } неверен?', '["feof работает только с двоичными файлами","fgets нельзя вызывать в цикле","feof устанавливается лишь после неудачного чтения: последний вызов fgets не прочитает ничего, а обработка выполнится","Цикл бесконечный"]', 2, 'Признак конца файла выставляется после неудачной попытки чтения. Проверяйте результат самой функции чтения: while (fgets(…)).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 8, 3, 'Какой результат даст strtol("42xyz", &end, 10)?', '["0 и ошибка","42, а end указывает на \"xyz\"","LONG_MAX","Неопределённое поведение"]', 1, 'strtol разбирает префикс, который годится как число, и сообщает, где остановилась: *end != 0 значит, что в строке остались посторонние символы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 8, 4, 'Зачем fgetc возвращает int, а не char?', '["Чтобы быстрее работать на 64-битных платформах","Чтобы можно было отличить признак конца EOF (−1) от кода любого настоящего символа","Потому что char нельзя вернуть из функции","Для совместимости с printf"]', 1, 'Результат — код символа от 0 до 255 или EOF. Если сохранить его в char, EOF может совпасть с настоящим символом 0xFF или никогда не распознаваться на платформах с беззнаковым char.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 9, 'theory', 'Квиз: представление данных');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 9, 0, 'Чему равно выражение -1 < 1u на 32-битной платформе?', '["1: потому что −1 меньше единицы","0: −1 переводится в беззнаковое 4294967295, и сравнение ложно","Результат зависит от порядка байтов","Неопределённое поведение"]', 1, 'При сравнении знакового с беззнаковым того же ранга знаковое приводится к беззнаковому: −1 становится 4294967295u. Сравнивайте значения одного знака или приводите их явно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 9, 1, 'Как безопасно получить 32 бита представления числа float f?', '["uint32_t b = *(uint32_t *)&f;","uint32_t b = (uint32_t)f;","Прочитать через указатель на int, приведя его к long","Скопировать байты: memcpy(&b, &f, sizeof b)"]', 3, 'Приведение указателя на другой тип нарушает строгий алиасинг, а приведение значения даёт число, а не биты. memcpy копирует байты, а компилятор превращает её в одну команду.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 9, 2, 'Чему равен sizeof(struct { char c; int i; char d; }) на обычной 64-битной платформе (int — 4 байта)?', '["12","6","8","16"]', 0, 'Между c и i — 3 байта прокладки, после d — 3 байта хвоста, чтобы элементы массива были выровнены: 1 + 3 + 4 + 1 + 3 = 12.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 9, 3, 'Как правильно сравнивать два вычисленных значения double на равенство?', '["Оператором == — как и целые","Через приведение обоих к int","С допуском: |a − b| меньше малого значения (абсолютного или относительного)","Сравнением строк, полученных printf"]', 2, 'Погрешность — свойство формата IEEE 754: 0.1 + 0.2 ≠ 0.3. Поэтому сравнивают с допуском либо по расстоянию в ulp.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 9, 4, 'Что делает выражение x & (x - 1) для ненулевого беззнакового x?', '["Выделяет младший единичный бит","Сбрасывает старший единичный бит","Меняет порядок байтов","Сбрасывает младший единичный бит"]', 3, 'Вычитание единицы инвертирует младший единичный бит и все нули под ним; «и» с исходным числом сбрасывает именно этот бит. Отсюда счёт единиц и проверка степени двойки.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 10, 'theory', 'Квиз: многофайловые проекты');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 10, 0, 'Чем объявление отличается от определения?', '["Объявление может быть только в .c, определение — только в .h","Определение можно повторять сколько угодно, объявление — один раз","Объявление сообщает имя и тип, определение создаёт сущность (память или код); определение должно быть одно на программу","Различия нет: это синонимы"]', 2, 'extern int x; и прототип функции — объявления, их может быть много. int x = 0; и тело функции — определения: два определения дают «multiple definition», ни одного — «undefined reference».');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 10, 1, 'Что делает слово static перед глобальной функцией или переменной в .c-файле?', '["Делает её доступной из всех файлов","Даёт внутреннее связывание: имя видно только в этом файле и не конфликтует с одноимёнными в других","Размещает её на стеке","Запрещает её изменять"]', 1, 'Это простейшая инкапсуляция в C: всё, что не входит в интерфейс модуля, помечают static. Внутри функции static — другое: переменная живёт между вызовами.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 10, 2, 'Почему статические библиотеки пишут в командной строке после объектных файлов, которые на них ссылаются?', '["Так требует препроцессор","Библиотека иначе не скопируется на диск","Порядок не имеет значения","Компоновщик просматривает архив один раз слева направо и берёт только объекты, нужные для уже известных неопределённых символов"]', 3, 'Если библиотека указана раньше, неопределённых символов ещё нет, и ни один её объект не извлекается. При циклических зависимостях библиотек используют группу (--start-group).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 10, 3, 'По какому признаку make решает пересобрать цель?', '["Цель отсутствует или старше любой из зависимостей по времени изменения","По размеру файла цели","По имени цели","По числу строк в исходниках"]', 0, 'make строит граф зависимостей и сравнивает время изменения: пересобирается только то, что зависит от изменённых файлов. Для этого нужно, чтобы зависимости были записаны верно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 10, 4, 'Какую проблему решают флаги компилятора -MMD -MP вместе с -include в Makefile?', '["Ускоряют компиляцию в несколько раз","Включают предупреждения","Автоматически записывают зависимости от заголовков, чтобы правка .h пересобирала использующие его .c","Заставляют компоновщик искать библиотеки"]', 2, 'make знает только записанные зависимости. Файлы .d, созданные компилятором, содержат реальные #include, и граф всегда актуален.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 11, 'theory', 'Квиз: неопределённое поведение, отладка и санитайзеры');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 11, 0, 'Что гарантирует стандарт при неопределённом поведении?', '["Программа обязательно аварийно завершится","Ничего: программа может работать, упасть, вернуть мусор или вести себя иначе в другой версии компилятора","Результат всегда будет нулём","Поведение определяется только операционной системой"]', 1, 'UB — это отсутствие гарантий. Компилятор вправе считать, что оно не происходит, и поэтому не проверяет такие случаи.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 11, 1, 'Почему проверка if (!p) после строки int v = p->a; может быть удалена оптимизатором?', '["Потому что условие записано неверно","Потому что указатели нельзя сравнивать с нулём","Из-за ошибки в линковщике","Раз p уже разыменован, оптимизатор вправе считать, что p не NULL, ведь иначе было бы UB"]', 3, 'Оптимизатор рассуждает от противного: корректная программа не содержит UB, поэтому после разыменования указатель не может быть нулевым. Проверку надо ставить до использования.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 11, 2, 'Какие ошибки находит -fsanitize=address?', '["Выход за границы кучи, стека и глобальных данных, use-after-free, double free (и утечки)","Только утечки памяти","Переполнение знаковых целых и сдвиги","Гонки данных между потоками"]', 0, 'ASan окружает блоки красными зонами и ведёт теневую карту. Переполнение знаковых и сдвиги ловит UBSan, гонки — TSan.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 11, 3, 'Для чего ключ -fno-sanitize-recover=all вместе с -fsanitize=undefined?', '["Чтобы отключить проверки","Чтобы ускорить программу","Чтобы программа останавливалась на первой найденной ошибке, а не продолжала работу","Чтобы включить также MemorySanitizer"]', 2, 'По умолчанию UBSan печатает сообщение и продолжает. В тестах нужен немедленный сбой, иначе ошибку легко не заметить среди вывода.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 11, 4, 'С какими ключами надо собирать программу для пошаговой отладки в gdb?', '["-O3 -DNDEBUG","-fsanitize=thread","-s -O2","-g -O0: отладочная информация и без оптимизаций, иначе переменные и строки «пропадают»"]', 3, 'Отладочная информация (-g) сопоставляет машинный код со строками и переменными, а оптимизации (-O2) переставляют и удаляют код, поэтому для отладки берут -O0.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 12, 'theory', 'Квиз: хеш-таблицы, деревья и кучи');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 12, 0, 'Почему при открытой адресации нельзя просто очистить ячейку удалённого элемента?', '["Потому что память нельзя освободить","Потому что ключи должны быть уникальными","Это замедлит хеш-функцию","Цепочка проб оборвётся, и элементы за ней станут «ненайденными»; нужно надгробие или сдвиг назад"]', 3, 'Поиск останавливается на пустой ячейке. Если очистить середину цепочки, ключи, которые лежали дальше, перестанут находиться. Помечают «надгробие» или сдвигают хвост цепочки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 12, 1, 'Что происходит с указателями на элементы таблицы после её роста (перестройки)?', '["Становятся недействительными: элементы переносятся в новый массив","Остаются действительными","Автоматически обновляются","Указывают на старые копии, которые можно безопасно читать"]', 0, 'При росте создаётся новый массив, и элементы вставляются заново; старый освобождается. Указатель внутрь таблицы после этого нельзя использовать.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 12, 2, 'Чему равно условие баланса АВЛ-дерева?', '["Все листья на одной глубине","Для каждого узла разность высот поддеревьев не больше 1 по модулю","Левое поддерево не меньше правого","Высота дерева равна числу узлов"]', 1, 'Это условие гарантирует высоту порядка log n. После вставки и удаления его восстанавливают вращениями.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 12, 3, 'Какие индексы у потомков и родителя элемента i в двоичной куче на массиве (нумерация с нуля)?', '["Потомки 2i и 2i + 1, родитель i / 2","Потомки i + 1 и i + 2, родитель i − 1","Потомки 2i + 1 и 2i + 2, родитель (i − 1) / 2","Потомки 2i − 1 и 2i, родитель i / 2 − 1"]', 2, 'Формулы 2i + 1, 2i + 2 и (i − 1) / 2 соответствуют корню в a[0]. Для нумерации с единицы они другие: 2i, 2i + 1 и i / 2.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 12, 4, 'Как надёжно проверять правильность своей структуры данных в тестах?', '["Вызывать функцию-инвариант после каждой операции и сравнивать результаты с простой моделью на тех же случайных операциях","Печатать содержимое и смотреть глазами","Достаточно одного теста на пустую структуру","Не нужно, если собралось без предупреждений"]', 0, 'Инвариант находит нарушение сразу, а сравнение с моделью (например, на массиве) — любые расхождения в результатах. Всё запускают под санитайзерами.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 13, 'theory', 'Квиз: тестирование и стиль кода');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 13, 0, 'Что должен возвращать тестовый исполняемый файл, чтобы сборка могла автоматически определить результат?', '["Всегда 0","Число пройденных тестов","Код 0 при успехе и ненулевой код при любом провале","Размер вывода"]', 2, 'Системы сборки и непрерывной интеграции смотрят только на код возврата: 0 — всё хорошо, иначе — провал.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 13, 1, 'Когда нужно использовать assert, а когда — возвращать код ошибки?', '["assert — для нарушений контракта (баги программы), код ошибки — для неверного пользовательского ввода и сбоев среды","assert — для ввода пользователя, код ошибки — для багов","Всегда assert","Всегда код ошибки, assert не нужен"]', 0, 'Нарушенное предусловие — ошибка вызывающего кода: остановка с сообщением. Неверный ввод — обычная ситуация, и вызывающий должен получить код ошибки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 13, 2, 'Зачем в тестах подставлять аллокатор, который отказывает на n-м вызове?', '["Чтобы тесты работали быстрее","Чтобы отключить санитайзер","Чтобы увеличить покрытие обычного пути","Чтобы проверить ветки обработки нехватки памяти: функция должна всё освободить и вернуть ошибку"]', 3, 'Ветки «malloc вернул NULL» в обычных тестах не выполняются. Внедрение отказов проверяет, что утечек и повреждений нет на каждом пути.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 13, 3, 'Почему 100% покрытие строк не гарантирует качества тестов?', '["Потому что gcov ошибается","Потому что тест может выполнять код и ничего не проверять","Потому что покрытие не учитывает комментарии","Потому что покрытие считается только для функций"]', 1, 'Покрытие показывает, что строки выполнялись, а не что результат проверен. Мутационное тестирование и осмысленные проверки дополняют его.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 13, 4, 'Какой подход к ресурсам считается хорошей практикой в функции с несколькими выделениями?', '["Освобождать на каждом пути вручную без единой точки выхода","Единый блок очистки в конце с переходом goto cleanup, где освобождаются все ресурсы","Не освобождать — это сделает система при выходе","Переменная-флаг и вложенные if на пять уровней"]', 1, 'Один блок очистки избегает дублирования освобождений и забытых путей. Указатели, переданные вызывающему, после передачи обнуляют, чтобы не освободить дважды.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 14, 'theory', 'Квиз: современный C — C11 и C23');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 14, 0, 'Чем -std=gnu11 отличается от -std=c11?', '["Ничем","gnu11 включает C23","c11 разрешает больше расширений","gnu11 включает ещё и расширения GNU (typeof, выражения-операторы и другие), c11 — строго стандарт"]', 3, 'Для переносимого кода выбирают -std=c11 (или c17) с -Wpedantic; расширения GNU удобны, но привязывают код к gcc и clang.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 14, 1, 'Что такое гибкий член массива (flexible array member)?', '["Последний член структуры — массив без длины (char data[]); данные идут сразу за полями в одном блоке","Массив фиксированного размера в начале структуры","Массив, размер которого меняется оператором sizeof","Указатель на динамический массив"]', 0, 'Память выделяют как sizeof(struct) + n · sizeof(элемента). sizeof структуры хвост не включает, а присваивание структур хвост не копирует.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 14, 2, 'Что обещает программист компилятору, объявляя параметры с restrict?', '["Что указатели не равны NULL","Что функция не изменит данные","Что через эти указатели не будет доступа к одним и тем же данным: области не пересекаются","Что указатели выровнены"]', 2, 'Обещание не проверяется: если областей пересекаются, результат неопределён. Поэтому у memcpy параметры restrict, а у memmove — нет.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 14, 3, 'Что гарантирует atomic_fetch_add(&x, 1)?', '["Что операция выполнится быстрее обычной","Что чтение, прибавление и запись выполняются как одна неделимая операция для остальных потоков","Что переменная окажется в регистре","Что порядок всех остальных операций не изменится"]', 1, 'Атомарность убирает гонку данных на этой переменной. Какие ещё действия видны другим потокам, определяет порядок памяти (acquire/release/seq_cst).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 14, 4, 'Что делает ckd_add(&r, a, b) из <stdckdint.h> (C23)?', '["Складывает с насыщением","Всегда завершает программу при переполнении","Возвращает сумму, а в r кладёт признак","Записывает сумму в r и возвращает true, если математический результат не поместился в тип r"]', 3, 'Функции ckd_add, ckd_sub, ckd_mul дают переносимую арифметику с проверкой переполнения без неопределённого поведения.');
